CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('patient','receptionist','doctor','lab_technician','pharmacist','cashier','admin') NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',failed_logins INT NOT NULL DEFAULT 0,locked_until DATETIME NULL,must_change_password BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_resets(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staff_profiles(user_id BIGINT UNSIGNED PRIMARY KEY,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,specialty_id BIGINT UNSIGNED NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS specialties(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL UNIQUE,consultation_fee DECIMAL(10,2) NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS patients(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,patient_no VARCHAR(20) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NULL UNIQUE,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,sex ENUM('female','male','other','undisclosed') NOT NULL,date_of_birth DATE NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(190) NULL,address_enc TEXT NULL,blood_group VARCHAR(5) NULL,genotype VARCHAR(5) NULL,allergies_enc TEXT NULL,nok_name VARCHAR(160) NULL,nok_relationship VARCHAR(80) NULL,nok_phone_enc TEXT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX patient_name(first_name,last_name),INDEX patient_dob(date_of_birth)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS doctor_schedules(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,doctor_id BIGINT UNSIGNED NOT NULL,weekday TINYINT UNSIGNED NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,slot_minutes SMALLINT UNSIGNED NOT NULL,FOREIGN KEY(doctor_id) REFERENCES users(id),UNIQUE KEY doctor_weekday(doctor_id,weekday)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS doctor_time_off(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,doctor_id BIGINT UNSIGNED NOT NULL,off_date DATE NOT NULL,reason VARCHAR(255) NULL,FOREIGN KEY(doctor_id) REFERENCES users(id),UNIQUE KEY doctor_off(doctor_id,off_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS appointments(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,appt_date DATE NOT NULL,slot_time TIME NOT NULL,status ENUM('booked','checked_in','in_consultation','completed','cancelled','no_show') NOT NULL DEFAULT 'booked',type ENUM('online_booking','walk_in') NOT NULL DEFAULT 'online_booking',reason VARCHAR(255) NULL,queue_no INT NULL,checked_in_at DATETIME NULL,reminder_sent_at DATETIME NULL,cancelled_at DATETIME NULL,cancel_reason VARCHAR(255) NULL,active_key TINYINT GENERATED ALWAYS AS (CASE WHEN status IN('booked','checked_in','in_consultation') THEN 1 ELSE NULL END) STORED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(doctor_id) REFERENCES users(id),UNIQUE KEY doctor_slot(doctor_id,appt_date,slot_time,active_key),INDEX appointment_queue(appt_date,doctor_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS visits(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,appointment_id BIGINT UNSIGNED NULL UNIQUE,patient_id BIGINT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,visit_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointments(id),FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(doctor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS diagnoses(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,code VARCHAR(30) UNIQUE,name VARCHAR(160) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS consultations(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,visit_id BIGINT UNSIGNED NOT NULL UNIQUE,chief_complaint_enc MEDIUMTEXT NULL,history_enc MEDIUMTEXT NULL,bp VARCHAR(20) NULL,temperature DECIMAL(4,1) NULL,pulse SMALLINT UNSIGNED NULL,respiratory_rate SMALLINT UNSIGNED NULL,spo2 DECIMAL(5,2) NULL,weight_kg DECIMAL(6,2) NULL,height_cm DECIMAL(6,2) NULL,diagnosis_id BIGINT UNSIGNED NULL,diagnosis_note_enc TEXT NULL,examination_enc MEDIUMTEXT NULL,treatment_plan_enc MEDIUMTEXT NULL,internal_note_enc MEDIUMTEXT NULL,follow_up_date DATE NULL,status ENUM('draft','finalized') NOT NULL DEFAULT 'draft',finalized_at DATETIME NULL,FOREIGN KEY(visit_id) REFERENCES visits(id),FOREIGN KEY(diagnosis_id) REFERENCES diagnoses(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS consultation_addenda(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,consultation_id BIGINT UNSIGNED NOT NULL,author_id BIGINT UNSIGNED NOT NULL,body_enc MEDIUMTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(consultation_id) REFERENCES consultations(id),FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lab_tests(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL UNIQUE,sample_type VARCHAR(80) NOT NULL,price DECIMAL(10,2) NOT NULL,unit VARCHAR(40) NULL,reference_low DECIMAL(12,4) NULL,reference_high DECIMAL(12,4) NULL,reference_text VARCHAR(255) NULL,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lab_requests(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,visit_id BIGINT UNSIGNED NOT NULL,test_id BIGINT UNSIGNED NOT NULL,ordered_by BIGINT UNSIGNED NOT NULL,note_enc TEXT NULL,status ENUM('requested','sample_collected','resulted','released','cancelled') NOT NULL DEFAULT 'requested',priority ENUM('routine','urgent') NOT NULL DEFAULT 'routine',requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,collected_at DATETIME NULL,resulted_at DATETIME NULL,released_at DATETIME NULL,result_value DECIMAL(14,4) NULL,result_text_enc MEDIUMTEXT NULL,flag ENUM('low','normal','high') NULL,FOREIGN KEY(visit_id) REFERENCES visits(id),FOREIGN KEY(test_id) REFERENCES lab_tests(id),FOREIGN KEY(ordered_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS drugs(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL,generic_name VARCHAR(160) NOT NULL,form VARCHAR(80) NOT NULL,strength VARCHAR(80) NOT NULL,unit_price DECIMAL(10,2) NOT NULL,reorder_level INT UNSIGNED NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS drug_batches(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,drug_id BIGINT UNSIGNED NOT NULL,batch_no VARCHAR(80) NOT NULL,expires_on DATE NOT NULL,qty_remaining INT UNSIGNED NOT NULL DEFAULT 0,cost DECIMAL(10,2) NOT NULL,FOREIGN KEY(drug_id) REFERENCES drugs(id),UNIQUE KEY drug_batch(drug_id,batch_no),CHECK(qty_remaining>=0),INDEX fefo(drug_id,expires_on)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_movements(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,batch_id BIGINT UNSIGNED NOT NULL,qty_delta INT NOT NULL,reason VARCHAR(255) NOT NULL,actor_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(batch_id) REFERENCES drug_batches(id),FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS prescriptions(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,visit_id BIGINT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,status ENUM('open','partial','dispensed','cancelled') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(visit_id) REFERENCES visits(id),FOREIGN KEY(doctor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS prescription_items(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,prescription_id BIGINT UNSIGNED NOT NULL,drug_id BIGINT UNSIGNED NOT NULL,dose VARCHAR(120) NOT NULL,frequency VARCHAR(120) NOT NULL,duration VARCHAR(120) NOT NULL,quantity INT UNSIGNED NOT NULL,allergy_override BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(prescription_id) REFERENCES prescriptions(id),FOREIGN KEY(drug_id) REFERENCES drugs(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dispensings(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,prescription_item_id BIGINT UNSIGNED NOT NULL,pharmacist_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(prescription_item_id) REFERENCES prescription_items(id),FOREIGN KEY(pharmacist_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS services(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL UNIQUE,price DECIMAL(10,2) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS invoices(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,invoice_no VARCHAR(30) NOT NULL UNIQUE,visit_id BIGINT UNSIGNED NOT NULL UNIQUE,status ENUM('open','partially_paid','paid','voided') NOT NULL DEFAULT 'open',voided_by BIGINT UNSIGNED NULL,void_reason VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(visit_id) REFERENCES visits(id),FOREIGN KEY(voided_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS invoice_items(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,invoice_id BIGINT UNSIGNED NOT NULL,item_type ENUM('consultation','lab','pharmacy','other') NOT NULL,ref_id BIGINT UNSIGNED NULL,description VARCHAR(255) NOT NULL,qty DECIMAL(10,2) NOT NULL DEFAULT 1,unit_price DECIMAL(10,2) NOT NULL,amount DECIMAL(12,2) NOT NULL,voided BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(invoice_id) REFERENCES invoices(id),UNIQUE KEY invoice_engine_line(invoice_id,item_type,ref_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,invoice_id BIGINT UNSIGNED NOT NULL,receipt_no VARCHAR(30) NOT NULL UNIQUE,kind ENUM('payment','reversal') NOT NULL DEFAULT 'payment',amount DECIMAL(12,2) NOT NULL,method ENUM('cash','pos','bank_transfer','adjustment') NOT NULL,reference VARCHAR(120) NULL,received_by BIGINT UNSIGNED NOT NULL,reason VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id),FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS break_glass_access(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,doctor_id BIGINT UNSIGNED NOT NULL,patient_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(500) NOT NULL,accessed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,review_note VARCHAR(500) NULL,FOREIGN KEY(doctor_id) REFERENCES users(id),FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,channel ENUM('email','sms','in_app') NOT NULL,subject VARCHAR(255) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sent_messages(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,channel VARCHAR(20) NOT NULL,recipient VARCHAR(190) NOT NULL,subject VARCHAR(255) NULL,body TEXT NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS counters(name VARCHAR(50) PRIMARY KEY,value BIGINT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings(name VARCHAR(80) PRIMARY KEY,value VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS job_runs(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,job_name VARCHAR(80) NOT NULL,status VARCHAR(30) NOT NULL,detail TEXT NULL,started_at DATETIME NOT NULL,finished_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NULL,detail TEXT NULL,ip VARCHAR(64) NULL,is_read_event BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX audit_time(created_at)) ENGINE=InnoDB;
